import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const authority = new URL(process.env.VOLTER_ACCOUNT_URL);
const response = await fetch(new URL('/.well-known/oauth-authorization-server', authority));
assert.equal(response.status, 200);
const metadata = await response.json();
assert.equal(metadata.issuer, 'https://auth.videogame.ai');
assert.equal(metadata.authorization_endpoint, 'https://auth.videogame.ai/account/authorize');
assert.equal(metadata.token_endpoint, 'https://auth.videogame.ai/account/token');
assert.deepEqual(metadata.grant_types_supported, ['authorization_code', 'refresh_token']);
assert.ok(metadata.code_challenge_methods_supported.includes('S256'));
assert.equal(metadata.device_authorization_endpoint, undefined);
console.log(JSON.stringify({ issuer: metadata.issuer, grants: metadata.grant_types_supported }));
